CREATE TABLE IF NOT EXISTS event (
  id                   TEXT PRIMARY KEY,
  account_id           TEXT NOT NULL,
  calendar_id          TEXT NOT NULL,
  external_account_id  TEXT NOT NULL,
  provider_calendar_id TEXT NOT NULL,
  provider_event_id    TEXT NOT NULL,
  title                TEXT NOT NULL,
  start                TEXT NOT NULL,
  end                  TEXT,
  all_day              INTEGER NOT NULL DEFAULT 0,
  location             TEXT,
  meeting_link         TEXT,
  organizer_email      TEXT,
  organizer_name       TEXT,
  organizer_self       INTEGER,
  attendees            TEXT,
  status               TEXT,
  updated_at           INTEGER,
  synced_at            INTEGER NOT NULL,
  UNIQUE (external_account_id, provider_calendar_id, provider_event_id)
);
CREATE INDEX IF NOT EXISTS idx_event_calendar_start ON event(calendar_id, start);
CREATE INDEX IF NOT EXISTS idx_event_window ON event(external_account_id, provider_calendar_id, start);
ALTER TABLE calendar ADD COLUMN sync_token TEXT;
ALTER TABLE calendar ADD COLUMN last_synced_at INTEGER;
ALTER TABLE calendar ADD COLUMN sync_status TEXT;
ALTER TABLE calendar ADD COLUMN sync_window_min INTEGER NOT NULL DEFAULT 7776000000;

ALTER TABLE calendar ADD COLUMN migration_status TEXT NOT NULL DEFAULT 'pending';
ALTER TABLE calendar ADD COLUMN last_migrated_at INTEGER;
ALTER TABLE calendar ADD COLUMN last_synced_through INTEGER;
CREATE TABLE IF NOT EXISTS calendar_migration_run (
  id                TEXT PRIMARY KEY,
  calendar_id       TEXT NOT NULL,
  kind              TEXT NOT NULL,
  started_at        INTEGER,
  completed_at      INTEGER,
  window_from       INTEGER,
  window_to         INTEGER,
  events_scanned    INTEGER,
  identities_found  INTEGER,
  status            TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_migration_run_calendar ON calendar_migration_run(calendar_id, started_at DESC);
